package br.com.patasunidas.adocoes

import br.com.patasunidas.data.UserProfile
import kotlinx.coroutines.runBlocking
import okhttp3.mockwebserver.MockResponse
import okhttp3.mockwebserver.MockWebServer
import org.json.JSONObject
import org.junit.Test
import org.junit.Assert.*

class AdoptionApiTest {
 private val record="""{"id":3,"animal":{"id":8,"nome":"Tito"},"ong":{"id":1,"nome":"ONG Teste"},"status":"PENDENTE","mensagem":null,"justificativaRejeicao":null,"justificativaCancelamento":null,"analisadoEm":null,"canceladoEm":null,"adocao":null,"createdAt":"2026-11-22T12:00:00Z","updatedAt":"2026-11-22T12:00:00Z","versao":0,"solicitante":null,"analisadoPor":null,"canceladoPor":null,"historico":[]}"""
 @Test fun criacaoEnviaSomenteAnimalEMensagem() = runBlocking {val s=MockWebServer();s.start();try{s.enqueue(MockResponse().setResponseCode(201).setBody(record));val r=AdoptionApi(s.url("/").toString()).create("jwt",8,"Mensagem");assertEquals("Tito",r.animalName);val q=s.takeRequest();assertEquals("/api/adoption-requests",q.path);assertEquals("Bearer jwt",q.getHeader("Authorization"));val j=JSONObject(q.body.readUtf8());assertEquals(setOf("animalId","mensagem"),j.keys().asSequence().toSet());assertEquals(8L,j.getLong("animalId"))}finally{s.shutdown()}}
 @Test fun listagemEConsultaUsamEscopoEPaginacao() = runBlocking {val s=MockWebServer();s.start();try{val api=AdoptionApi(s.url("/").toString());s.enqueue(MockResponse().setBody("""{"content":[$record],"number":2,"totalPages":4,"totalElements":61}"""));val p=api.list("jwt",true,2,AdoptionStatus.APROVADA,8);assertEquals(2,p.page);assertEquals(61L,p.total);assertEquals("/api/ong/adoption-requests?page=2&size=20&status=APROVADA&animalId=8",s.takeRequest().path);s.enqueue(MockResponse().setBody(record));api.details("jwt",false,3);assertEquals("/api/me/adoption-requests/3",s.takeRequest().path)}finally{s.shutdown()}}
 @Test fun entregaExigeBooleanoExplicito() = runBlocking {val s=MockWebServer();s.start();try{val api=AdoptionApi(s.url("/").toString());try{api.act("jwt",true,3,AdoptionAction.DELIVER,confirmed=false);fail()}catch(_:IllegalArgumentException){};assertEquals(0,s.requestCount);s.enqueue(MockResponse().setBody(record.replace("PENDENTE","CONCLUIDA")));api.act("jwt",true,3,AdoptionAction.DELIVER,confirmed=true);val q=s.takeRequest();assertEquals("POST",q.method);assertEquals("/api/ong/adoption-requests/3/confirmar-entrega",q.path);assertTrue(JSONObject(q.body.readUtf8()).getBoolean("entregaConfirmada"))}finally{s.shutdown()}}
 @Test fun rejeicaoECancelamentosUsamMetodosECorposReais() = runBlocking {val s=MockWebServer();s.start();try{val api=AdoptionApi(s.url("/").toString());for((a,path) in listOf(AdoptionAction.REJECT to "/api/ong/adoption-requests/3/rejeitar",AdoptionAction.CANCEL_APPROVAL to "/api/ong/adoption-requests/3/cancelar-aprovacao",AdoptionAction.CANCEL to "/api/me/adoption-requests/3/cancelar",AdoptionAction.APPROVE to "/api/ong/adoption-requests/3/aprovar")){s.enqueue(MockResponse().setBody(record));api.act("jwt",a!=AdoptionAction.CANCEL,3,a,reason="Motivo");val q=s.takeRequest();assertEquals("PATCH",q.method);assertEquals(path,q.path);if(a in listOf(AdoptionAction.REJECT,AdoptionAction.CANCEL_APPROVAL))assertEquals("Motivo",JSONObject(q.body.readUtf8()).getString("justificativa"))}}finally{s.shutdown()}}
 @Test fun errosHttpSaoPreservadosSemReenvio() = runBlocking {val s=MockWebServer();s.start();try{for(code in listOf(400,401,403,404,409,429)){s.enqueue(MockResponse().setResponseCode(code));try{AdoptionApi(s.url("/").toString()).details("jwt",false,3);fail()}catch(e:AdoptionHttpException){assertEquals(code,e.status)}};assertEquals(6,s.requestCount)}finally{s.shutdown()}}
 @Test fun acoesRespeitamCincoPerfisEEstados() {for(p in UserProfile.entries){assertEquals(p==UserProfile.ADMINISTRADOR||p==UserProfile.VOLUNTARIO,canManageAdoptions(p));assertTrue(actionsFor(AdoptionStatus.CONCLUIDA,p).isEmpty());if(p==UserProfile.VETERINARIO||p==UserProfile.ADMIN_PLATAFORMA)assertTrue(actionsFor(AdoptionStatus.PENDENTE,p).isEmpty())};assertEquals(listOf(AdoptionAction.CANCEL),actionsFor(AdoptionStatus.APROVADA,UserProfile.USUARIO));assertTrue(AdoptionAction.DELIVER in actionsFor(AdoptionStatus.APROVADA,UserProfile.VOLUNTARIO));assertFalse(AdoptionAction.DELIVER in actionsFor(AdoptionStatus.PENDENTE,UserProfile.ADMINISTRADOR))}
}
